"""Data-led goal visuals, within Friday's existing Soft Studio design system."""
PLAYBOOK_CSS = r'''
.goal-playbook{margin-top:22px;display:grid;gap:20px;white-space:normal}.playbook-section h3{font-size:17px;margin:0 0 12px;letter-spacing:-.025em}.playbook-allocation{display:grid;grid-template-columns:120px 1fr;gap:20px;align-items:center;background:var(--panel2);padding:18px;border-radius:20px}.playbook-donut{width:116px;height:116px;border-radius:50%;position:relative;display:grid;place-items:center}.playbook-donut:before{content:'';position:absolute;inset:14px;background:var(--panel);border-radius:50%}.playbook-donut>div{position:relative;text-align:center}.playbook-donut strong{font-size:19px;display:block}.playbook-donut small{font-size:10px;color:var(--muted)}.playbook-legend{display:grid;gap:8px}.playbook-legend>div{display:flex;justify-content:space-between;gap:10px;font-size:12px}.playbook-legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}.playbook-legend strong{white-space:nowrap}.playbook-route{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.playbook-checkpoint{padding:14px 10px;border-radius:18px;background:var(--studio-lilac);border:1px solid var(--line);min-width:0}.playbook-checkpoint[data-reached=true]{background:var(--studio-mint)}.playbook-checkpoint small{font-size:10px;color:var(--muted);display:block;line-height:1.5}.playbook-checkpoint strong{font-size:14px;display:block;margin:7px 0;overflow-wrap:anywhere}.playbook-badge{display:inline-flex;padding:5px 9px;border-radius:20px;background:var(--panel);font-size:11px}.playbook-note{font-size:11px;line-height:1.6;color:var(--muted);margin:9px 0 0}.playbook-pressure{border:1px solid var(--line);border-radius:18px;padding:4px 15px}.playbook-pressure>summary{font-size:13px;min-height:48px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:10px;color:var(--ink)}.playbook-pressure>summary:after{content:'+';font-size:22px}.playbook-pressure[open]>summary:after{content:'−'}.playbook-case{padding:14px 0;border-top:1px solid var(--line)}.playbook-case-header{display:flex;justify-content:space-between;gap:12px;font-size:12px;line-height:1.6}.playbook-track{height:9px;background:var(--panel2);border-radius:20px;margin:10px 0;overflow:hidden}.playbook-fill{height:100%;border-radius:20px;background:#64a48e}.playbook-case[data-gap=true] .playbook-fill{background:#ba7255}.playbook-alternatives{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-top:14px}.playbook-option{background:var(--studio-lilac);border-radius:16px;padding:15px}.playbook-option strong{display:block;font-size:17px;margin:8px 0}.playbook-option small{font-size:11px;line-height:1.6}.playbook-factors{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.playbook-factors span{padding:5px 8px;background:var(--studio-mint);border-radius:20px;font-size:10px}.playbook-investments{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:12px}.playbook-investments article{border-radius:15px;background:var(--panel2);padding:13px}.playbook-investments strong{font-size:13px}.playbook-investments p{font-size:11px;line-height:1.6}.playbook-investments a{font-size:11px;color:var(--blue)}.roadmap-root .goal-permission{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:10px 12px;border:1px solid var(--line);border-radius:14px;background:var(--panel2);font-size:11px}.goal-permission[hidden]{display:none!important}.goal-permission button{min-height:40px;font-size:12px}.goal-permission span{flex:1;min-width:180px}.goal-confirmation{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.roadmap-root .friday-chat-log:has(.goal-playbook){max-height:none;overflow:visible}.roadmap-root .goal-panel:has(.goal-playbook){border-radius:22px}.goal-investment-prompt{display:block;margin-top:12px}
@media(max-width:600px){.playbook-route{grid-template-columns:repeat(2,minmax(0,1fr))}.playbook-allocation{grid-template-columns:1fr}.playbook-donut{margin:auto}.playbook-investments{grid-template-columns:1fr}.playbook-case-header{flex-wrap:wrap}.playbook-legend>div{font-size:11px}.roadmap-root .friday-chat-log:has(.goal-playbook){max-height:none}}
'''

PLAYBOOK_JS = r'''
      function renderGoalPlaybook(s,parent){
        const book=s.playbook;if(!book)return;
        const wrap=element('div',null,'goal-playbook');wrap.setAttribute('aria-label','Your goal action plan');
        const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-IN',{month:'short',year:'numeric'}):'Not yet reachable';
        const split=element('section',null,'playbook-section');split.append(element('h3','A place for every monthly rupee'));
        const allocation=element('div',null,'playbook-allocation'),donut=element('div',null,'playbook-donut');
        const colours=['#8d78c5','#d49b7e','#64a48e','#d8cbed'],total=book.allocation.slices.reduce((n,v)=>n+Number(v.amount_inr),0);let cursor=0;
        const stops=book.allocation.slices.map((v,i)=>{const start=cursor;cursor+=total?Number(v.amount_inr)/total*100:0;return colours[i]+' '+start+'% '+cursor+'%';});
        donut.style.background=total?'conic-gradient('+stops.join(',')+')':'var(--line)';donut.setAttribute('role','img');donut.setAttribute('aria-label','Monthly allocation; exact amounts in the adjacent legend. Not a health or credit score.');
        const centre=element('div');centre.append(element('strong',book.allocation.goal_income_percent===null?'—':book.allocation.goal_income_percent+'%'),element('small','income to goal'));donut.append(centre);
        const legend=element('div',null,'playbook-legend');book.allocation.slices.forEach((v,i)=>{const row=element('div'),label=element('span'),dot=element('i');dot.style.background=colours[i];label.append(dot,document.createTextNode(v.label));row.append(label,element('strong',money(v.amount_inr)));legend.append(row);});allocation.append(donut,legend);split.append(allocation);
        if(Number(book.allocation.overspend_inr)>0)split.append(element('p','Living costs and debt exceed income by '+money(book.allocation.overspend_inr)+'/month. The ring shows costs, not a balanced budget.','goal-budget-warning'));
        else split.append(element('p','Monthly take-home '+money(book.allocation.income_inr)+' · Unallocated money is not a promise that every expense is covered.','playbook-note'));
        if(Number(s.protected_reserve_gap_inr)>0)split.append(element('p','Reserve first: '+money(s.protected_reserve_gap_inr)+' of future contributions fills your protected buffer before the goal.','playbook-note'));
        wrap.append(split);
        const route=element('section',null,'playbook-section');route.append(element('h3','Your next checkpoints'));const path=element('div',null,'playbook-route');
        book.checkpoints.forEach(m=>{const card=element('div',null,'playbook-checkpoint');card.dataset.reached=String(m.reached);card.append(element('span',(m.reached?'✓ ': '')+m.percent+'%','playbook-badge'),element('strong',money(m.target_inr)),element('small',m.reached?'Reported reached':dateLabel(m.estimated_date)+(m.after_deadline?' · after target date':'')));path.append(card);});route.append(path,element('p','Future dates are cash scenarios. Only your reported savings fill the progress meter.','playbook-note'));wrap.append(route);
        const failing=book.scenarios.filter(c=>!c.reaches_target).length;
        const pressure=element('details',null,'playbook-pressure');pressure.append(element('summary','Pressure tests · '+(failing?failing+' scenarios miss the target':'target covered in these scenarios')));
        book.scenarios.forEach(c=>{const card=element('div',null,'playbook-case');card.dataset.gap=String(!c.reaches_target);const head=element('div',null,'playbook-case-header');head.append(element('strong',c.label),element('span',c.reaches_target?'Target covered':money(c.gap_inr)+' short'));const track=element('div',null,'playbook-track'),fill=element('div',null,'playbook-fill');fill.style.width=Math.min(100,Number(c.end_inr)/Number(c.target_inr)*100)+'%';track.append(fill);card.append(head,track,element('small',money(c.end_inr)+' projected / '+money(c.target_inr)+' target','playbook-note'),element('p',c.assumption,'playbook-note'));pressure.append(card);});
        pressure.append(element('p','Illustrations, not likelihoods or a complete risk assessment. No investment returns, taxes or actual price forecasts are included.','playbook-note'));wrap.append(pressure);
        if(book.alternatives.length){const options=element('section',null,'playbook-section');options.append(element('h3','Make the plan fit your life'));const cards=element('div',null,'playbook-alternatives');book.alternatives.forEach(a=>{const c=element('article',null,'playbook-option');c.append(element('small',a.label),element('strong',a.code==='MORE_TIME'?dateLabel(a.date):a.code==='SMALLER_TARGET'?money(a.target_inr):a.code==='EXTRA_CAPACITY'?'+'+money(a.extra_monthly_inr)+'/mo':'Review cash flow'),element('small',a.code==='NO_TIMELINE'?'No feasible date within 60 months at this monthly capacity.':a.code==='EXTRA_CAPACITY'?'Extra recurring capacity needed; don’t cut essential bills.':money(a.monthly_inr)+'/month · '+a.months+' future contributions'));if(['MORE_TIME','SMALLER_TARGET'].includes(a.code))c.append(btn('Preview this option',()=>previewAlternative(a)));cards.append(c);});options.append(cards,element('p','Preview an option without saving it. Your saved priority changes only after Confirm & save.','playbook-note'));wrap.append(options);}
        const factors=element('details',null,'playbook-pressure');factors.append(element('summary','What this plan checks · and what it can’t know'));const tags=element('div',null,'playbook-factors');book.review_factors.forEach(v=>tags.append(element('span','✓ '+v.toLowerCase().replaceAll('_',' '))));factors.append(tags,element('p','Using your stated assumptions, not verified bank balances.','playbook-note'));book.not_established.forEach(v=>factors.append(element('p','Not established · '+v,'playbook-note')));wrap.append(factors);
        const learn=element('details',null,'playbook-pressure');learn.append(element('summary','Savings, mutual funds & shares · learn before deciding'));const investments=element('div',null,'playbook-investments');
        [['Cash & deposits','Check access, rate, provider protection and early-withdrawal terms. This plan assumes no interest.','Asset classes','https://investor.sebi.gov.in/investment-assetclasses.html'],['Mutual funds','Value can fall. Compare scheme Riskometer, fees, exit loads and liquidity; an SIP is not a guaranteed return.','AMFI risks','https://www.amfiindia.com/investor/knowledge-center-info?zoneName=riskInMutualFunds'],['Shares & gold','Prices can move against your goal. A higher past return is not a promise; check concentration and costs.','Before investing','https://investor.sebi.gov.in/investment-thingsbeforeinv.html']].forEach(([name,note,label,url])=>{const card=element('article');card.append(element('strong',name),element('p',note));const link=element('a',label);link.href=url;link.target='_blank';link.rel='noopener noreferrer';card.append(link);investments.append(card);});
        learn.append(investments,element('p','Education only, not a scheme recommendation or personalised asset allocation. No broker, live holdings or trading connection. Market-linked holdings are not treated as guaranteed cash.','playbook-note'),btn('Ask Friday to explain investment choices',()=>{const text='Explain savings deposits, mutual funds and shares: risks, liquidity, fees and what to check. No personalised buy/sell advice or promised returns.';focusFriday(text);root.roadmapAssistant(text);},'planner goal-investment-prompt'));wrap.append(learn);parent.append(wrap);
      }
'''
